llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Meclofenamate, an N-aryl anthranilic acid with a carboxylic acid and halogenated rings, has human oral bioavailability above 85%, directly supporting high bioavailability for the query's anthranilic acid core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Flufenamic acid, another anthranilic acid derivative, shows good oral bioavailability and rapid absorption in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Diflunisal, a halogenated carboxylic acid, has absolute bioavailability of 89.5% in a volunteer, supporting high oral bioavailability for the acidic query molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Telmisartan, a carboxylic acid-containing drug, has absolute bioavailability of 42–57% in fasting volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Celecoxib, a sulfonamide-containing drug with poor aqueous solubility, still has oral bioavailability of 20–40%, indicating that the sulfonamide group does not push F below the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Pazopanib, another sulfonamide-containing drug, has absolute bioavailability of 21.4% (range 13.5–38.9%), remaining at or above the 20% threshold despite variability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues have absolute oral bioavailability at or above 20%, including structurally related anthranilic acid fenamates with >85% bioavailability and carboxylic acid/sulfonamide drugs with 21–57% bioavailability. No evidence supports F < 20%, so the query is predicted high.",
  "evidence_gaps": [
    "No direct furosemide bioavailability measurement is present in the evidence set.",
    "No cystic fibrosis-specific pharmacokinetic data are available; disease-related GI changes could affect absorption but are unlikely to reduce F below 20%.",
    "The query's furfurylamine and chlorine substituents are not directly represented among the analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

